/*
 * Vote Sticker profile pictures, votesticker.org.
 *
 * Pick a state, see every design in every palette, save one as a 1080 px PNG. Everything is drawn
 * on a canvas in the browser; nothing is uploaded. Data: states.js (dates, links) and
 * state-shapes.js (outlines, generated by build/build_shapes.py). Notes: ../README.md.
 *
 * Every design keeps its content inside a 500 px radius of the center. Facebook, Instagram, X and
 * LinkedIn show a profile picture as a circle of 540 px radius on this canvas, so nothing is cut.
 */
(function () {
	'use strict';

	var SIZE = 1080, STORY_H = 1920, SAFE = 500, BADGE_SAFE = 430, RING_R = 506;
	var DISPLAY = '"Vote Display"', DATE = '"Vote Date"';

	var PALETTES = [
		{ id: 'cream', name: 'Cream and navy', bg: '#FBF8F0', ink: '#14295E', accent: '#C1272D', onAccent: '#FBF8F0' },
		{ id: 'navy', name: 'Navy and red', bg: '#0F2558', ink: '#FBF6E8', accent: '#B3262C', onAccent: '#FBF6E8' },
		{ id: 'forest', name: 'Forest and gold', bg: '#0A3D2C', ink: '#FBF6E8', accent: '#D4AF4A', onAccent: '#0A3D2C' },
		{ id: 'sand', name: 'Sand and rust', bg: '#EBDABF', ink: '#1F1E1C', accent: '#A9552A', onAccent: '#FBF6E8' },
		{ id: 'sky', name: 'Sky and navy', bg: '#D4E8FA', ink: '#14295E', accent: '#C1272D', onAccent: '#FBF8F0' },
		{ id: 'sage', name: 'Sage and forest', bg: '#8FAF88', ink: '#0B3A23', accent: '#E0BC4E', onAccent: '#0B3A23' }
	];
	// Big type first: at 40 to 60 px, the size most people see a profile picture, it reads best (October 19).
	var DESIGNS = [
		{ id: 'type', name: 'Big type' },
		{ id: 'shape', name: 'State shape' },
		{ id: 'badge', name: 'Badge' }
	];
	// Two short lines each, so a card still reads at 40 px in a comment thread (Garrett, October 19).
	// `early` headlines only where a verified row has early voting, `mail` only in all-mail states;
	// everywhere else the card says VOTE NOV 3.
	var HEADLINES = {
		early: { early: true, label: 'Vote early', lines: ['VOTE', 'EARLY'] },
		mail: { mail: true, label: 'Vote by mail', lines: ['VOTE', 'BY MAIL'] },
		nov3: { dated: true, label: 'Vote Nov 3', lines: ['VOTE', 'NOV 3'] },
		voting: { early: true, label: 'I\u2019m voting early', lines: ['I\u2019M VOTING', 'EARLY'] },
		voted: { early: true, label: 'I voted early', lines: ['I VOTED', 'EARLY'] },
		imvoting: { label: 'I\u2019m voting', lines: ['I\u2019M', 'VOTING'] },
		state: { label: '[State] votes', lines: function (st) { return [(st.abbr === 'DC' ? 'DC' : st.name.toUpperCase()), 'VOTES']; } }
	};

	function hasEarly(st) { return st.status === 'verified' && st.kind !== 'none'; }
	function headlinesFor(st) {
		return Object.keys(HEADLINES).filter(function (k) {
			var h = HEADLINES[k];
			return (!h.early || hasEarly(st)) && (!h.mail || (hasEarly(st) && st.kind === 'mail'));
		});
	}
	function defaultHeadline(st) { return !hasEarly(st) ? 'nov3' : st.kind === 'mail' ? 'mail' : 'early'; }
	function headlineLines(key, st) {
		var h = HEADLINES[key] || HEADLINES.nov3;
		return typeof h.lines === 'function' ? h.lines(st) : h.lines;
	}
	var MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
	var MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
	var DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

	var ELECTION = window.VOTE_ELECTION, STATES = window.VOTE_STATES, SHAPES = window.VOTE_SHAPES;
	var byAbbr = {};
	STATES.forEach(function (s) { byAbbr[s.abbr] = s; });

	/* ------------------------------------------------------------------ */
	/* Small helpers                                                       */
	/* ------------------------------------------------------------------ */
	function $(id) { return document.getElementById(id); }
	function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
	function load(key, fallback) { try { var v = localStorage.getItem('vote-cards:' + key); return v ? JSON.parse(v) : fallback; } catch (e) { return fallback; } }
	function save(key, value) { try { localStorage.setItem('vote-cards:' + key, JSON.stringify(value)); } catch (e) { /* private window */ } }

	function day(iso) { var p = iso.split('-'); return new Date(+p[0], +p[1] - 1, +p[2]); }
	function shortDate(d) { return MONTHS[d.getMonth()] + ' ' + d.getDate(); }
	function longDate(d) { return DAYS[d.getDay()] + ', ' + MONTHS_LONG[d.getMonth()] + ' ' + d.getDate(); }
	function slug(name) { return name.toLowerCase().replace(/[^a-z]+/g, '-'); }

	// "OCT 19–30", or "OCT 24–NOV 1" across a month.
	function rangeLine(a, b) {
		if (a.getMonth() === b.getMonth()) { return MONTHS[a.getMonth()] + ' ' + a.getDate() + '–' + b.getDate(); }
		return shortDate(a) + '–' + shortDate(b);
	}

	function electionLine() { return DAYS[day(ELECTION.day).getDay()].toUpperCase() + ' ' + shortDate(day(ELECTION.day)); }

	// The date line a state's cards start with. Only verified rows show early voting dates.
	// The date line a card starts with, for a state and headline. A headline that already carries the
	// date (VOTE NOV 3) gets ELECTION DAY under it.
	function defaultDateLine(st, headline) {
		if (headline && HEADLINES[headline] && HEADLINES[headline].dated) { return 'ELECTION DAY'; }
		if (!hasEarly(st)) { return electionLine(); }
		if (st.dateLine) { return st.dateLine; }
		if (st.kind === 'mail') { return 'DUE ' + shortDate(day(st.end)); }
		if (!st.start || !st.end) { return electionLine(); }
		return rangeLine(day(st.start), day(st.end));
	}

	function luminance(hex) {
		var n = parseInt(hex.slice(1), 16);
		return [n >> 16, (n >> 8) & 255, n & 255].map(function (c) {
			c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
		}).reduce(function (sum, c, i) { return sum + c * [0.2126, 0.7152, 0.0722][i]; }, 0);
	}
	function contrast(a, b) { var x = luminance(a), y = luminance(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }

	/* ------------------------------------------------------------------ */
	/* State outlines                                                      */
	/* ------------------------------------------------------------------ */
	var shapeCache = {};
	function shape(abbr) {
		if (shapeCache[abbr]) { return shapeCache[abbr]; }
		var s = SHAPES[abbr];
		var pts = [];
		s.d.replace(/(-?\d+),(-?\d+)/g, function (m, x, y) { pts.push([+x, +y]); return m; });
		return (shapeCache[abbr] = { w: s.w, h: s.h, cap: s.cap, path: new Path2D(s.d), pts: pts });
	}

	/* ------------------------------------------------------------------ */
	/* Layout: each design returns items in its own units, then fit()       */
	/* scales and centers them so every point sits inside the safe circle.  */
	/* ------------------------------------------------------------------ */
	var measureCtx = document.createElement('canvas').getContext('2d');

	// Text sized so its widest line's ink is `width` wide, capped at `maxAsc` tall.
	function textBlock(lines, family, width, maxAsc) {
		measureCtx.font = '200px ' + family;
		measureCtx.textBaseline = 'alphabetic';
		var ms = lines.map(function (l) { return measureCtx.measureText(l); });
		var widest = Math.max.apply(null, ms.map(function (m) { return m.actualBoundingBoxLeft + m.actualBoundingBoxRight; }));
		var asc = Math.max.apply(null, ms.map(function (m) { return m.actualBoundingBoxAscent; }));
		var k = width / widest;
		if (maxAsc && asc * k > maxAsc) { k = maxAsc / asc; }
		return {
			family: family, size: 200 * k, asc: asc * k, gap: asc * k * 0.12,
			lines: lines.map(function (l, i) {
				var m = ms[i];
				return { s: l, w: (m.actualBoundingBoxLeft + m.actualBoundingBoxRight) * k, left: m.actualBoundingBoxLeft * k };
			})
		};
	}

	// Place a text block centered on cx with its top at `top`. Returns the items and the bottom.
	function placeText(block, cx, top, color) {
		var items = [], y = top;
		block.lines.forEach(function (l, i) {
			if (i) { y += block.gap; }
			var base = y + block.asc;
			items.push({ t: 'text', s: l.s, font: block.size + 'px ' + block.family, color: color,
				x: cx - l.w / 2 + l.left, base: base, box: [cx - l.w / 2, y, cx + l.w / 2, base] });
			y = base;
		});
		return { items: items, bottom: y };
	}

	function iconItem(st, cx, top, h, maxW, color, star) {
		var sh = shape(st.abbr), k = Math.min(h / sh.h, maxW / sh.w);
		var w = sh.w * k, x = cx - w / 2;
		var items = [{ t: 'shape', abbr: st.abbr, x: x, y: top, k: k, color: color }];
		if (star) { items.push({ t: 'star', cx: x + sh.cap[0] * k, cy: top + sh.cap[1] * k, r: Math.max(sh.w, sh.h) * k * 0.09, color: star }); }
		return { items: items, bottom: top + sh.h * k };
	}

	function dateItems(text, cx, top, width, maxAsc, color, boxColor) {
		var block = textBlock([text], DATE, width, maxAsc);
		if (!boxColor) { return placeText(block, cx, top, color); }
		var padY = block.asc * 0.34, padX = block.asc * 0.5;
		var placed = placeText(block, cx, top + padY, color);
		var w = block.lines[0].w;
		placed.items.unshift({ t: 'box', box: [cx - w / 2 - padX, top, cx + w / 2 + padX, placed.bottom + padY], color: boxColor });
		placed.bottom += padY;
		return placed;
	}

	function boxesHit(a, b) { return a[0] < b[2] && b[0] < a[2] && a[1] < b[3] && b[1] < a[3]; }

	var LAYOUTS = {
		// The state filled in ink, the headline in the background color with an ink outline, a star on the capital, dates below.
		shape: function (st, p, lines, dateText) {
			var sh = shape(st.abbr), k = Math.min(1000 / sh.w, 800 / sh.h);
			var w = sh.w * k, h = sh.h * k, x = -w / 2;
			var shapeItem = { t: 'shape', abbr: st.abbr, x: x, y: 0, k: k, color: p.ink };
			var head = textBlock(lines, DISPLAY, Math.min(Math.max(w * 0.78, 560), 800));
			var headH = head.asc * lines.length + head.gap * (lines.length - 1);
			var headTop = h * 0.48 - headH / 2;
			var placed = placeText(head, 0, headTop, p.ink);
			var sw = head.size * 0.07;
			placed.items.forEach(function (it) {
				it.color = p.bg; it.stroke = p.ink; it.strokeWidth = sw;
				it.box = [it.box[0] - sw / 2, it.box[1] - sw / 2, it.box[2] + sw / 2, it.box[3] + sw / 2];
			});
			var items = [shapeItem].concat(placed.items);
			var r = Math.max(w, h) * 0.045, star = { t: 'star', cx: x + sh.cap[0] * k, cy: sh.cap[1] * k, r: r, color: p.accent };
			var starBox = [star.cx - r * 1.4, star.cy - r * 1.4, star.cx + r * 1.4, star.cy + r * 1.4];
			if (!placed.items.some(function (it) { return boxesHit(it.box, starBox); })) { items.push(star); }
			var date = dateItems(dateText, 0, Math.max(h, placed.bottom) + head.asc * 0.3, Math.min(Math.max(w * 0.8, 560), 760), head.asc * 0.5, p.ink);
			return { items: items.concat(date.items), safe: SAFE };
		},
		// A small state on top, the headline as big as it goes, dates in the accent color.
		type: function (st, p, lines, dateText) {
			var icon = iconItem(st, 0, 0, 120, 220, p.ink, p.accent);
			var head = textBlock(lines, DISPLAY, 760);
			var placed = placeText(head, 0, icon.bottom + 44, p.ink);
			var plain = contrast(p.accent, p.bg) >= 3;
			var date = dateItems(dateText, 0, placed.bottom + head.asc * 0.22, plain ? 760 : 680, head.asc * (plain ? 0.78 : 0.62),
				plain ? p.accent : p.onAccent, plain ? null : p.accent);
			return { items: icon.items.concat(placed.items, date.items), safe: SAFE };
		},
		// A ring at the edge of the circle crop, the state, the headline, dates on an accent bar.
		badge: function (st, p, lines, dateText) {
			var icon = iconItem(st, 0, 0, 110, 200, p.ink, p.accent);
			var head = textBlock(lines, DISPLAY, 640);
			var placed = placeText(head, 0, icon.bottom + 36, p.ink);
			var date = dateItems(dateText, 0, placed.bottom + head.asc * 0.2, 520, head.asc * 0.42, p.onAccent, p.accent);
			return { items: icon.items.concat(placed.items, date.items), safe: BADGE_SAFE, ring: p.ink };
		}
	};

	function itemPoints(it) {
		if (it.t === 'shape') {
			return shape(it.abbr).pts.map(function (q) { return [it.x + q[0] * it.k, it.y + q[1] * it.k]; });
		}
		var b = it.t === 'star' ? [it.cx - it.r, it.cy - it.r, it.cx + it.r, it.cy + it.r] : it.box;
		return [[b[0], b[1]], [b[2], b[1]], [b[0], b[3]], [b[2], b[3]]];
	}

	// Scale and center so the farthest point of any item lands on the safe circle.
	function fit(layout) {
		var pts = [];
		layout.items.forEach(function (it) { pts = pts.concat(itemPoints(it)); });
		var xs = pts.map(function (q) { return q[0]; }), ys = pts.map(function (q) { return q[1]; });
		var cx = (Math.min.apply(null, xs) + Math.max.apply(null, xs)) / 2;
		var cy = (Math.min.apply(null, ys) + Math.max.apply(null, ys)) / 2;
		var far = Math.max.apply(null, pts.map(function (q) { return Math.hypot(q[0] - cx, q[1] - cy); }));
		return { s: layout.safe / far, cx: cx, cy: cy, far: far };
	}

	/* ------------------------------------------------------------------ */
	/* Drawing                                                             */
	/* ------------------------------------------------------------------ */
	function drawStar(ctx, cx, cy, r) {
		ctx.beginPath();
		for (var i = 0; i < 10; i++) {
			var a = -Math.PI / 2 + i * Math.PI / 5, rr = i % 2 ? r * 0.42 : r;
			ctx.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr);
		}
		ctx.closePath();
		ctx.fill();
	}

	function drawShape(ctx, it) {
		ctx.save();
		ctx.translate(it.x, it.y);
		ctx.scale(it.k, it.k);
		ctx.fill(shape(it.abbr).path);
		ctx.restore();
	}

	function drawItem(ctx, it) {
		ctx.fillStyle = it.color;
		if (it.t === 'shape') { drawShape(ctx, it); return; }
		if (it.t === 'star') { drawStar(ctx, it.cx, it.cy, it.r); return; }
		if (it.t === 'box') { ctx.fillRect(it.box[0], it.box[1], it.box[2] - it.box[0], it.box[3] - it.box[1]); return; }
		ctx.font = it.font;
		ctx.textBaseline = 'alphabetic';
		ctx.textAlign = 'left';
		if (it.stroke) {
			// Background-colored letters with an ink outline: over the state the outline melts into
			// the fill, outside it the letter is outlined, so a ragged coastline never cuts a letter.
			ctx.lineJoin = 'round';
			ctx.lineWidth = it.strokeWidth;
			ctx.strokeStyle = it.stroke;
			ctx.strokeText(it.s, it.x, it.base);
		}
		ctx.fillText(it.s, it.x, it.base);
	}

	// Draw one card on a canvas `px` pixels wide: square, or a 9:16 Story with the same card in the
	// middle. No site address on any image (Garrett, October 19).
	function render(canvas, px, opts) {
		var st = byAbbr[opts.state], p = PALETTES.filter(function (x) { return x.id === opts.palette; })[0];
		var layout = LAYOUTS[opts.design](st, p, headlineLines(opts.headline, st), opts.dateText);
		var f = fit(layout);
		var tall = opts.story ? STORY_H : SIZE;
		canvas.width = px;
		canvas.height = Math.round(px * tall / SIZE);
		var ctx = canvas.getContext('2d');
		ctx.setTransform(px / SIZE, 0, 0, px / SIZE, 0, 0);
		ctx.fillStyle = p.bg;
		ctx.fillRect(0, 0, SIZE, tall);
		if (opts.story) {
			ctx.translate(0, (tall - SIZE) / 2);
		}
		if (layout.ring) {
			ctx.strokeStyle = layout.ring;
			ctx.lineWidth = 12;
			ctx.beginPath();
			ctx.arc(SIZE / 2, SIZE / 2, RING_R, 0, Math.PI * 2);
			ctx.stroke();
		}
		ctx.translate(SIZE / 2, SIZE / 2);
		ctx.scale(f.s, f.s);
		ctx.translate(-f.cx, -f.cy);
		layout.items.forEach(function (it) { drawItem(ctx, it); });
		return f;
	}

	/* ------------------------------------------------------------------ */
	/* Saving: the Softball Austin card maker's rules, by device           */
	/* ------------------------------------------------------------------ */
	var DEVICE = (function () {
		var ua = navigator.userAgent || '';
		if (/iPhone|iPad|iPod/i.test(ua) || (/Macintosh/i.test(ua) && (navigator.maxTouchPoints || 0) > 1)) { return 'ios'; }
		if (/Android/i.test(ua)) { return 'android'; }
		return 'desktop';
	})();
	var SHARE_TO_PHOTOS = (function () {
		if (DEVICE !== 'ios') { return false; }
		try {
			var probe = new File([new Blob(['x'], { type: 'image/png' })], 'probe.png', { type: 'image/png' });
			return !!navigator.canShare && navigator.canShare({ files: [probe] });
		} catch (e) { return false; }
	})();
	var TIPS = {
		ios: SHARE_TO_PHOTOS ? 'Tap Save to Photos, then Save Image. Then set it as your profile picture from Photos.' : 'Tap Open image, press and hold the picture, and choose Save to Photos.',
		android: 'The picture saves to your Downloads. Set it as your profile picture from there.',
		desktop: 'The picture saves to your Downloads folder.'
	};

	var current = { blob: null, url: null, name: '' };
	function wireSave(link) {
		link.addEventListener('click', function (e) {
			if (!current.blob) { e.preventDefault(); return; }
			if (!SHARE_TO_PHOTOS) { return; }
			e.preventDefault();
			var file = new File([current.blob], current.name, { type: 'image/png' });
			navigator.share({ files: [file] }).catch(function (err) {
				// Closing the share sheet is not an error; anything else falls back to the download.
				if (err && err.name === 'AbortError') { return; }
				window.location.href = current.url;
			});
		});
	}

	/* ------------------------------------------------------------------ */
	/* Page                                                                */
	/* ------------------------------------------------------------------ */
	var state = {
		state: null,
		headline: 'nov3',
		dateEdited: false,
		design: load('design', 'type'),
		palette: load('palette', 'navy'),
		dateText: '',
		circle: load('circle', true),
		story: false
	};
	var previewSeq = 0;

	function opts() {
		return { state: state.state, design: state.design, palette: state.palette, headline: state.headline, dateText: state.dateText.toUpperCase() };
	}

	function infoHtml(st) {
		var lookup = 'https://www.vote411.org/' + slug(st.name);
		var eday = 'Election Day is ' + ELECTION.label + '.';
		if (st.status !== 'verified') {
			return '<h2>Vote by ' + shortDate(day(ELECTION.day)).replace(/^(\w)(\w+)/, function (m, a, b) { return a + b.toLowerCase(); }) + '</h2><p>We haven’t checked ' + esc(st.name) + '’s early voting dates yet, so these pictures show Election Day. ' +
				'Look up your dates and polling place at <a href="' + lookup + '" target="_blank" rel="noopener">Vote411</a> ' +
				'(League of Women Voters) or your state election office.</p><p>' + eday + '</p>';
		}
		var html = '<h2>' + (st.kind === 'mail' ? 'Vote by mail' : st.kind === 'none' ? 'Vote on Election Day' : 'Vote early') + '</h2><p><b>';
		if (st.summary) {
			html += esc(st.summary);
		} else if (st.kind === 'mail') {
			html += esc(st.name) + ' votes by mail. Return your ballot by ' + longDate(day(st.end)) + '.';
		} else if (st.kind === 'none') {
			html += esc(st.name) + ' doesn\u2019t have early voting open to everyone. Most voters vote on Election Day, ' + ELECTION.label + '.';
		} else {
			html += 'Early voting in ' + esc(st.name) + ' runs ' + longDate(day(st.start)) + ' to ' + longDate(day(st.end)) + '.';
		}
		html += '</b> ' + (st.kind === 'none' ? '' : eday) + '</p>';
		if (st.note) { html += '<p>' + esc(st.note) + '</p>'; }
		html += '<p><a href="' + esc(st.officialUrl) + '" target="_blank" rel="noopener">' + (st.kind === 'none' ? 'Voting information at ' : 'Find your polling place at ') + esc(st.officialLabel) + '</a></p>';
		html += '<p class="source">Dates from the <a href="' + esc(st.sourceUrl) + '" target="_blank" rel="noopener">state election office</a>, checked ' +
			longDate(day(st.checked)).replace(/^\w+, /, '') + ', ' + st.checked.slice(0, 4) + '.</p>';
		return html;
	}

	function postText(st) {
		if (st.status === 'verified' && st.summary) {
			return st.summary + ' Details at ' + st.officialLabel + '.';
		}
		if (st.status === 'verified' && st.kind === 'mail') {
			return st.name + ' votes by mail. Return your ballot by ' + MONTHS_LONG[day(st.end).getMonth()] + ' ' + day(st.end).getDate() + '. Details at ' + st.officialLabel + '.';
		}
		if (st.status === 'verified' && st.kind === 'in-person') {
			var a = day(st.start), b = day(st.end);
			var range = MONTHS_LONG[a.getMonth()] + ' ' + a.getDate() + ' to ' + (a.getMonth() === b.getMonth() ? '' : MONTHS_LONG[b.getMonth()] + ' ') + b.getDate();
			return 'Early voting in ' + st.name + ' runs ' + range + '. Find your polling place at ' + st.officialLabel + '.';
		}
		if (st.status === 'verified' && st.kind === 'none') {
			return 'Election Day in ' + st.name + ' is ' + ELECTION.label + '. Make a plan to vote. Polling places and absentee rules are at ' + st.officialLabel + '.';
		}
		return 'Election Day is ' + ELECTION.label + '. Make a plan to vote, and check whether you can vote early in ' + st.name + ' at vote411.org.';
	}

	function buildGrid() {
		var grid = $('grid');
		grid.innerHTML = '';
		DESIGNS.forEach(function (d) {
			PALETTES.forEach(function (p) {
				var b = document.createElement('button');
				b.type = 'button';
				b.className = 'tile';
				b.dataset.design = d.id;
				b.dataset.palette = p.id;
				b.setAttribute('aria-label', d.name + ', ' + p.name);
				b.setAttribute('aria-pressed', String(d.id === state.design && p.id === state.palette));
				var c = document.createElement('canvas');
				b.appendChild(c);
				grid.appendChild(b);
			});
		});
	}

	function drawGrid() {
		var px = Math.round(Math.min(window.devicePixelRatio || 1, 2) * 180);
		Array.prototype.forEach.call(document.querySelectorAll('#grid .tile'), function (b) {
			var o = opts();
			o.design = b.dataset.design;
			o.palette = b.dataset.palette;
			render(b.querySelector('canvas'), px, o);
		});
	}

	function drawPreview() {
		var seq = ++previewSeq;
		var canvas = document.createElement('canvas');
		var o = opts();
		o.story = state.story;
		render(canvas, SIZE, o);
		var link = $('save');
		link.setAttribute('aria-disabled', 'true');
		canvas.toBlob(function (blob) {
			if (seq !== previewSeq || !blob) { return; }
			if (current.url) { URL.revokeObjectURL(current.url); }
			current.blob = blob;
			current.url = URL.createObjectURL(blob);
			current.name = 'vote-early-' + state.state.toLowerCase() + '-' + state.design + '-' + state.palette + (state.story ? '-story' : '') + '.png';
			$('preview').src = current.url;
			link.href = current.url;
			link.download = current.name;
			$('open').href = current.url;
			link.removeAttribute('aria-disabled');
		}, 'image/png');
	}

	function setPressed() {
		Array.prototype.forEach.call(document.querySelectorAll('#grid .tile'), function (b) {
			b.setAttribute('aria-pressed', String(b.dataset.design === state.design && b.dataset.palette === state.palette));
		});
	}

	function showState(abbr, keepDate) {
		var st = byAbbr[abbr];
		if (!st) { $('maker').hidden = true; return; }
		state.state = abbr;
		// Each state starts on its own headline; the menu lists only the ones true for it.
		var headSel = $('headline');
		headSel.innerHTML = '';
		headlinesFor(st).forEach(function (k) {
			var o = document.createElement('option');
			o.value = k;
			o.textContent = k === 'state' ? (st.abbr === 'DC' ? 'DC' : st.name) + ' votes' : HEADLINES[k].label;
			headSel.appendChild(o);
		});
		if (!keepDate || headlinesFor(st).indexOf(state.headline) < 0) { state.headline = defaultHeadline(st); }
		headSel.value = state.headline;
		if (!keepDate) { state.dateText = defaultDateLine(st, state.headline); state.dateEdited = false; }
		$('date').value = state.dateText;
		$('info').innerHTML = infoHtml(st);
		$('post-text').value = postText(st);
		var plain = (st.status === 'verified' ? (st.summary || $('info').querySelector('b').textContent) : st.name + ': Election Day is ' + ELECTION.label + '.') +
			(st.status === 'verified' ? ' Official info: ' + st.officialLabel : '');
		$('summary').textContent = plain;
		setAlt();
		showGallery(st);
		$('maker').hidden = false;
		drawGrid();
		drawPreview();
	}

	// Hand-made pictures for the state, listed by index.php from assets/states/<abbr>/.
	function showGallery(st) {
		var files = (window.VOTE_GALLERY || {})[st.abbr] || [];
		$('gallery').hidden = !files.length;
		// States with ready-made pictures lead with them; the maker follows as "Or Make Your Own" (October 19).
		$('gallery-h').textContent = 'Ready-Made ' + st.name + ' Stickers';
		$('maker-h').hidden = !files.length;
		document.body.classList.toggle('has-gallery', !!files.length);
		var grid = $('gallery-grid');
		grid.innerHTML = '';
		files.forEach(function (src, i) {
			var name = 'vote-' + st.abbr.toLowerCase() + '-' + (i + 1) + '.jpg';
			var a = document.createElement('a');
			a.className = 'tile';
			a.href = src;
			a.download = name;
			var img = document.createElement('img');
			img.src = src;
			img.alt = st.name + ' vote picture, hand-made design ' + (i + 1);
			img.width = img.height = 1080;
			img.loading = 'lazy';
			a.appendChild(img);
			grid.appendChild(a);
		});
	}

	function setAlt() {
		var st = byAbbr[state.state];
		$('preview').alt = 'Profile picture: ' + headlineLines(state.headline, st).join(' ') + ', ' + st.name + '. ' + $('summary').textContent;
	}

	function redraw() { drawGrid(); drawPreview(); }

	function init() {
		var sel = $('state');
		STATES.forEach(function (s) {
			var o = document.createElement('option');
			o.value = s.abbr;
			o.textContent = s.name;
			sel.appendChild(o);
		});
		var headSel = $('headline');
		$('circle').checked = state.circle;
		document.body.classList.toggle('as-circle', state.circle);
		$('tip').textContent = TIPS[DEVICE];
		$('save').textContent = SHARE_TO_PHOTOS ? 'Save to Photos' : 'Download picture';
		wireSave($('save'));
		buildGrid();

		sel.addEventListener('change', function () {
			var meta = (window.VOTE_META || {})[sel.value];
			if (meta) { window.location.href = (window.VOTE_BASE || '/') + meta.slug + '/'; }
		});
		headSel.addEventListener('change', function () {
			state.headline = headSel.value;
			// The date line follows the headline until someone types their own.
			if (!state.dateEdited) { state.dateText = defaultDateLine(byAbbr[state.state], state.headline); $('date').value = state.dateText; }
			setAlt();
			redraw();
		});
		$('date').addEventListener('input', function () { state.dateText = $('date').value; state.dateEdited = true; redraw(); });
		$('date-reset').addEventListener('click', function () { showState(state.state); });
		Array.prototype.forEach.call(document.querySelectorAll('[data-size]'), function (b) {
			b.addEventListener('click', function () {
				state.story = b.dataset.size === 'story';
				Array.prototype.forEach.call(document.querySelectorAll('[data-size]'), function (x) { x.setAttribute('aria-pressed', String(x === b)); });
				document.body.classList.toggle('is-story', state.story);
				drawPreview();
			});
		});
		$('circle').addEventListener('change', function () {
			state.circle = $('circle').checked;
			save('circle', state.circle);
			document.body.classList.toggle('as-circle', state.circle);
		});
		$('grid').addEventListener('click', function (e) {
			var b = e.target.closest('.tile');
			if (!b) { return; }
			state.design = b.dataset.design;
			state.palette = b.dataset.palette;
			save('design', state.design);
			save('palette', state.palette);
			setPressed();
			drawPreview();
			var top = $('preview').getBoundingClientRect().top;
			if (top < 0 || top > window.innerHeight * 0.6) { $('preview-wrap').scrollIntoView({ behavior: 'smooth', block: 'start' }); }
		});
		$('copy').addEventListener('click', function () {
			var t = $('post-text');
			var done = function () { $('copy').textContent = 'Copied'; setTimeout(function () { $('copy').textContent = 'Copy post text'; }, 2000); };
			if (navigator.clipboard && navigator.clipboard.writeText) {
				navigator.clipboard.writeText(t.value).then(done, function () { t.select(); document.execCommand('copy'); done(); });
			} else { t.select(); document.execCommand('copy'); done(); }
		});

		// Copy this page's link (its own share image and title go with it). Phones that can share get
		// the share sheet instead; the clipboard is the fallback everywhere.
		var shareBtn = $('share-link');
		if (shareBtn) {
			var shareUrl = shareBtn.dataset.url, shareTitle = shareBtn.dataset.title, shareLabel = $('share-label').textContent;
			var said = function (t) { $('share-label').textContent = t; setTimeout(function () { $('share-label').textContent = shareLabel; }, 2200); };
			shareBtn.addEventListener('click', function () {
				if (navigator.share && /Android|iPhone|iPad/.test(navigator.userAgent)) {
					navigator.share({ title: shareTitle, url: shareUrl }).catch(function () {});
					return;
				}
				var copied = function () { said('Link copied'); };
				var fallback = function () {
					var t = document.createElement('textarea');
					t.value = shareUrl; t.setAttribute('readonly', ''); t.style.position = 'fixed'; t.style.left = '-9999px';
					document.body.appendChild(t); t.select();
					try { document.execCommand('copy'); copied(); } catch (e) { said('Copy this: ' + shareUrl); }
					document.body.removeChild(t);
				};
				if (navigator.clipboard && navigator.clipboard.writeText) { navigator.clipboard.writeText(shareUrl).then(copied, fallback); } else { fallback(); }
			});
		}

		// Each state has its own page (/<slug>/, rendered by index.php); the menu goes there.
		var start = window.VOTE_PAGE_STATE;
		if (byAbbr[start]) { sel.value = start; showState(start); }
	}

	function fonts() {
		var base = (window.VOTE_ASSETS || 'assets/') + 'fonts/';
		return Promise.all([
			new FontFace(DISPLAY.replace(/"/g, ''), 'url(' + base + 'anton.woff2)'),
			new FontFace(DATE.replace(/"/g, ''), 'url(' + base + 'archivo-black.woff2)')
		].map(function (f) { return f.load().then(function (l) { document.fonts.add(l); }); }));
	}

	// For the QA script: draw any card and report how far its content reaches from the center.
	window.VOTE_CARDS = { render: render, fit: fit, LAYOUTS: LAYOUTS, PALETTES: PALETTES, DESIGNS: DESIGNS, HEADLINES: HEADLINES, headlinesFor: headlinesFor, defaultHeadline: defaultHeadline, defaultDateLine: defaultDateLine, SAFE: SAFE };

	fonts().then(init, function () { init(); });
})();
